oint comments retained");var edit=StructuredChangeRequest.DraftBody(new JsonObject{["ctoId"]="cto",["reason"]="Revised requirement"},revision);edit["points"]![0]!["text"]="Posting clarified";Act(snapshot,worker,row,"save",edit);ChangeRequests.Upload(snapshot,worker,row,new JsonObject{["id"]="doc2",["paragraphCount"]=100});Deny(()=>Act(snapshot,worker,row,"submit",new JsonObject()));edit["amendmentResponses"]=new JsonArray(StructuredChangeRequest.PriorNotes(row).Select(n=>(JsonNode)new JsonObject{["key"]=J.S(n,"key"),["reply"]="Updated as requested"}).ToArray());Act(snapshot,worker,row,"save",edit);Act(snapshot,worker,row,"submit",new JsonObject());Deny(()=>Act(snapshot,pm,row,"review",new JsonObject{["decision"]="Approve"}));Act(snapshot,pm,row,"review",new JsonObject{["decision"]="Approve",["checkedPrevious"]=true});Check(J.S(revision,"state")=="Pending CTO","PM approval routes to CTO");Act(snapshot,cto,row,"review",new JsonObject{["decision"]="Amendment",["comment"]="Update the second form wording"});string secondRevision=revision.ToJsonString();Act(snapshot,worker,row,"revise",new JsonObject{["reason"]="Address CTO comment"});revision=ChangeRequests.Latest(row);var third=StructuredChangeRequest.DraftBody(new JsonObject{["ctoId"]="cto",["reason"]="CTO amendment completed"},revision);third["points"]![1]!["text"]="Second form wording updated";third["amendmentResponses"]=new JsonArray(StructuredChangeRequest.PriorNotes(row).Where(n=>J.N(n,"revision")==2&&J.S(n,"decision")!="Approve").Select(n=>(JsonNode)new JsonObject{["key"]=J.S(n,"key"),["reply"]="Updated second form"}).ToArray());Act(snapshot,worker,row,"save",third);ChangeRequests.Upload(snapshot,worker,row,new JsonObject{["id"]="doc3",["paragraphCount"]=100});Act(snapshot,worker,row,"submit",new JsonObject());Act(snapshot,pm,row,"review",new JsonObject{["decision"]="Approve",["checkedPrevious"]=true});Deny(()=>Act(snapshot,cto,row,"review",new JsonObject{["decision"]="Approve"}));Act(snapshot,cto,row,"review",ne